const IMG_MATCHA_COMIGO = "data:image/jpeg;base64,";
const IMG_MATCHARIA = "data:image/jpeg;base64,";
const IMG_DEU_MATCHA = "data:image/jpeg;base64,";
const IMG_MOCHA = "data:image/jpeg;base64,";
const IMG_CAFE = "data:image/jpeg;base64,";
const IMG_COOKIES = "data:image/jpeg;base64,";
const IMG_MOCHI = "data:image/jpeg;base64,";

/* =========================================================
   DADOS DOS PRODUTOS
========================================================= */

const ICON_SHIBA = "data:image/svg+xml;base64,";
const ICON_CART = "data:image/svg+xml;base64,";
const ICON_HOT_SELECTED = "data:image/svg+xml;base64,";
const ICON_COLD_SELECTED = "data:image/svg+xml;base64,";
const ICON_HOT_OUTLINE = "data:image/svg+xml;base64,";
const ICON_COLD_OUTLINE = "data:image/svg+xml;base64,";
const ICON_SNACKS = "data:image/svg+xml;base64,";
const ICON_STAR = "data:image/svg+xml;base64,";
const ICON_DRINKS_OUTLINE = "data:image/svg+xml;base64,";
const ICON_DRINKS_SELECTED = "data:image/svg+xml;base64,";
const BANNER_PROMO_MATCHA_COMIGO = "data:image/png;base64,";
const BANNER_PROMO_DEU_MATCHA = "data:image/png;base64,";
const BANNER_FIDELIDADE = "data:image/png;base64,";
const iconImg = (src, cls='ui-icon') => `<img class="${cls}" src="${src}" alt="">`;

const PRODUCTS = {
  matcharia: {
    id:'matcharia', name:'Matcharia', category:'bebida',
    desc:'Contém matchá, limão e mel.', price:12.90, ml:'250 ml',
    photo:IMG_MATCHARIA, icon:'🍵'
  },
  mocha: {
    id:'mocha', name:'Mocha', category:'bebida',
    desc:'Contém café, leite integral e calda de chocolate.', price:10.90, ml:'250 ml',
    photo:IMG_MOCHA, icon:'☕'
  },
  matchaComigo: {
    id:'matchaComigo', name:'Matcha Comigo?', category:'bebida',
    desc:'Contém geleia de morango, leite e matchá.', price:10.90, ml:'250 ml',
    photo:IMG_MATCHA_COMIGO, icon:'🍓'
  },
  deuMatcha: {
    id:'deuMatcha', name:'Deu Matchá', category:'bebida',
    desc:'Matchá com cubos de gelo de café. Frescor e energia a qualquer hora.', price:11.90, ml:'250 ml',
    photo:IMG_DEU_MATCHA, icon:'🍵'
  },
  cafe: {
    id:'cafe', name:'Café', category:'bebida',
    desc:'Café coado tradicional, torra média, servido quente.', price:7.90, ml:'250 ml',
    photo:IMG_CAFE, icon:'☕'
  },
  cookies: {
    id:'cookies', name:'Cookies', category:'petisco',
    desc:'Cookies artesanais recheados, sabores tradicional e duplo chocolate.', price:7.90, ml:'un.',
    photo:IMG_COOKIES, icon:'🍪'
  },
  mochi: {
    id:'mochi', name:'Mochi', category:'petisco',
    desc:'Docinhos japoneses macios, sortidos em vários sabores.', price:9.90, ml:'2 un.',
    photo:IMG_MOCHI, icon:'🍡'
  }
};

const HIGHLIGHTS = ['mocha','matcharia','matchaComigo'];
const CHAS = ['matcharia','deuMatcha','matchaComigo'];
const CAFES = ['mocha','cafe'];
const COOKIES = ['cookies'];
const MOCHIS = ['mochi'];

const BANNERS = [
  {img:BANNER_PROMO_MATCHA_COMIGO, caption:''},
  {img:BANNER_PROMO_DEU_MATCHA, caption:''},
  {img:BANNER_FIDELIDADE, caption:''}
];

const SIZE_LABELS = {P:'Matchinho (250 ml)', G:'Matchão (400 ml)'};
const SIZE_EXTRA = {P:0, G:2.00};
const TEMP_LABELS = {quente:'Quente', gelado:'Gelado'};

/* =========================================================
   ESTADO
========================================================= */
let cart = [];          // {uid, productId, size, temp, qty, unitPrice}
let currentProduct = null;
let currentSize = 'P';
let currentTemp = 'gelado';
let currentQty = 1;
let checkoutStage = 'cart'; // cart | payment | processing | success
let selectedPayment = null;

/* =========================================================
   HELPERS
========================================================= */
function fmt(v){ return 'R$ ' + v.toFixed(2).replace('.', ','); }
function uid(){ return Math.random().toString(36).slice(2,9); }

function photoOrPlaceholder(p, cls){
  if(p.photo){
    return `<img class="${cls}" src="${p.photo}" alt="${p.name}" onerror="this.outerHTML='<div class=\\'${cls} placeholder\\' style=\\'background:linear-gradient(135deg,#f3ead2,#efe0c2)\\'>${p.icon}</div>'">`;
  }
  return `<div class="${cls} placeholder" style="background:linear-gradient(135deg,#f3ead2,#efe0c2)">${p.icon}</div>`;
}

/* =========================================================
   RENDER: cards de produto
========================================================= */
function renderGrid(containerId, ids){
  const el = document.getElementById(containerId);
  el.innerHTML = ids.map(id => {
    const p = PRODUCTS[id];
    const action = p.category === 'petisco'
      ? `quickAddPetisco('${id}')`
      : `openProduct('${id}')`;

    return `
    <div class="prod-card" onclick="${action}">
      ${photoOrPlaceholder(p,'prod-photo')}
      <button class="prod-add" aria-label="Adicionar ${p.name} à sacola"
        onclick="event.stopPropagation(); ${action}">+</button>
      <div class="prod-body">
        <p class="prod-name">${p.name}</p>
        <p class="prod-desc">${p.desc}</p>
        <div class="prod-foot">
          <span class="prod-price">${fmt(p.price)}</span>
          <span class="prod-ml">${p.ml}</span>
        </div>
      </div>
    </div>`;
  }).join('');
}

function renderAllGrids(){
  renderGrid('gridDestaques', HIGHLIGHTS);
  renderGrid('gridChas', CHAS);
  renderGrid('gridCafes', CAFES);
  renderGrid('gridCookies', COOKIES);
  renderGrid('gridMochi', MOCHIS);
}

/* =========================================================
   RENDER: banner carrossel
========================================================= */
let bannerIndex = 0, bannerTimer = null;
function renderBanner(){
  const track = document.getElementById('bannerTrack');
  const dots = document.getElementById('bannerDots');
  track.innerHTML = BANNERS.map(b => `
    <div class="banner-slide">
      <img src="${b.img}" alt="" onerror="this.style.display='none'">
      ${b.caption ? `<div class="banner-caption">${b.caption}</div>` : ``}
    </div>`).join('');
  dots.innerHTML = BANNERS.map((_,i)=>`<span class="${i===0?'active':''}"></span>`).join('');
  updateBannerPos();
}
function updateBannerPos(){
  document.getElementById('bannerTrack').style.transform = `translateX(-${bannerIndex*100}%)`;
  [...document.getElementById('bannerDots').children].forEach((d,i)=> d.classList.toggle('active', i===bannerIndex));
}
function startBannerAuto(){
  clearInterval(bannerTimer);
  bannerTimer = setInterval(()=>{
    bannerIndex = (bannerIndex+1) % BANNERS.length;
    updateBannerPos();
  }, 4200);
}

/* =========================================================
   NAVEGAÇÃO ENTRE TELAS
========================================================= */
function goHomeFromSplash(){
  document.getElementById('screen-splash').classList.remove('active');
  showPage('home');
}
function showPage(page){
  document.querySelectorAll('.screen').forEach(s=>s.classList.remove('active'));
  document.getElementById('screen-'+page).classList.add('active');
  if(page==='home'){ startBannerAuto(); }
}

/* =========================================================
   BOTTOM BAR (sacola + navegação) — injetada em cada página
========================================================= */
function bottomBarHTML(activePage){
  const count = cart.reduce((a,i)=>a+i.qty,0);
  const total = cart.reduce((a,i)=>a+i.unitPrice*i.qty,0);
  return `
    <div class="bag-row" onclick="openCart()">
      <div class="bag-icon-wrap">
        ${iconImg(ICON_CART)}
        ${count>0? `<span class="bag-badge">${count}</span>` : ''}
      </div>
      <span class="bag-label">SACOLA</span>
      <span class="bag-total">${fmt(total)}</span>
    </div>
    <div class="bag-actions">
      <button class="btn-fill" onclick="openCart()">Ver pedido</button>
      <button class="btn-outline" onclick="cancelOrder()">Cancelar pedido</button>
    </div>
    <div class="cat-quicknav">
      <button class="${activePage==='home'?'active':''}" onclick="showPage('home')"><span class="qn-dot">${iconImg(ICON_STAR)}</span>Destaques</button>
      <button class="${activePage==='bebidas'?'active':''}" onclick="showPage('bebidas')"><span class="qn-dot">${iconImg(activePage==='bebidas'?ICON_DRINKS_SELECTED:ICON_DRINKS_OUTLINE)}</span>Bebidas</button>
      <button class="${activePage==='petiscos'?'active':''}" onclick="showPage('petiscos')"><span class="qn-dot">${iconImg(ICON_SNACKS)}</span>Petiscos</button>
    </div>
  `;
}
function renderBottomBars(){
  document.getElementById('bottomBar-home').innerHTML = bottomBarHTML('home');
  document.getElementById('bottomBar-bebidas').innerHTML = bottomBarHTML('bebidas');
  document.getElementById('bottomBar-petiscos').innerHTML = bottomBarHTML('petiscos');
}

/* =========================================================
   MODAL: opções do produto (tamanho + temperatura)
========================================================= */
function openProduct(id){
  currentProduct = PRODUCTS[id];
  currentSize = 'P';
  currentTemp = 'gelado';
  currentQty = 1;
  renderProductSheet();
  document.getElementById('overlayProduct').classList.add('active');
}
function closeProduct(){
  document.getElementById('overlayProduct').classList.remove('active');
}
function selectSize(size){ currentSize = size; renderProductSheet(); }
function selectTemp(temp){ currentTemp = temp; renderProductSheet(); }
function changeQty(delta){ currentQty = Math.max(1, currentQty+delta); renderProductSheet(); }

function renderProductSheet(){
  const p = currentProduct;
  const unit = p.price + SIZE_EXTRA[currentSize];
  document.getElementById('sheetProduct').innerHTML = `
    <button class="sheet-close" onclick="closeProduct()">✕</button>
    <p class="sheet-title">Opções do produto</p>
    ${photoOrPlaceholder(p,'modal-photo')}
    <p class="prod-name" style="font-size:19px;margin-bottom:4px;">${p.name}</p>
    <p class="modal-desc">${p.desc}</p>

    <div class="opt-row">
      <div class="opt-label"><span>Tamanho</span><span>obrigatório</span></div>
      <div class="opt-choices">
        <button class="opt-choice ${currentSize==='P'?'selected':''}" onclick="selectSize('P')">Matchinho · 250ml</button>
        <button class="opt-choice ${currentSize==='G'?'selected':''}" onclick="selectSize('G')">Matchão · 400ml (+R$2,00)</button>
      </div>
    </div>

    <div class="opt-row">
      <div class="opt-label"><span>Temperatura</span><span>obrigatório</span></div>
      <div class="opt-choices">
        <button class="opt-choice ${currentTemp==='quente'?'selected':''}" onclick="selectTemp('quente')">${iconImg(currentTemp==='quente'?ICON_HOT_SELECTED:ICON_HOT_OUTLINE)} Quente</button>
        <button class="opt-choice ${currentTemp==='gelado'?'selected':''}" onclick="selectTemp('gelado')">${iconImg(currentTemp==='gelado'?ICON_COLD_SELECTED:ICON_COLD_OUTLINE)} Gelado</button>
      </div>
    </div>

    <div class="qty-row">
      <div class="qty-ctrl">
        <button class="qty-btn" onclick="changeQty(-1)">−</button>
        <span class="qty-num">${currentQty}</span>
        <button class="qty-btn" onclick="changeQty(1)">+</button>
      </div>
      <span class="modal-price">${fmt(unit*currentQty)}</span>
    </div>

    <button class="btn-continuar" onclick="addToCart()">ADICIONAR À SACOLA</button>
  `;
}

function addToCart(){
  const p = currentProduct;
  const unitPrice = p.price + SIZE_EXTRA[currentSize];
  cart.push({
    uid: uid(), productId: p.id, name:p.name, size:currentSize, temp:currentTemp,
    qty:currentQty, unitPrice, photo:p.photo, icon:p.icon
  });
  closeProduct();
  renderBottomBars();
  showToast('Produto adicionado à sacola');
}

/* Petiscos são produtos fixos: entram diretamente na sacola,
   sem tela de tamanho ou temperatura. */
function quickAddPetisco(id){
  const p = PRODUCTS[id];
  cart.push({
    uid: uid(),
    productId: p.id,
    name: p.name,
    size: '',
    temp: '',
    qty: 1,
    unitPrice: p.price,
    photo: p.photo,
    icon: p.icon
  });
  renderBottomBars();
  showToast(`${p.name} adicionado à sacola`);
}

/* =========================================================
   TOAST
========================================================= */
let toastTimer=null;
function showToast(msg){
  const t = document.getElementById('toast');
  document.getElementById('toastMsg').textContent = msg;
  t.classList.add('show');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(()=> t.classList.remove('show'), 2000);
}

/* =========================================================
   SACOLA / CHECKOUT
========================================================= */
function openCart(){
  checkoutStage='cart';
  renderCartSheet();
  document.getElementById('overlayCart').classList.add('active');
}
function closeCart(){
  document.getElementById('overlayCart').classList.remove('active');
}
function cancelOrder(){
  if(cart.length===0){ showToast('A sacola já está vazia'); return; }
  cart = [];
  renderBottomBars();
  renderCartSheet();
  showToast('Pedido cancelado');
}
function removeItem(uidToRemove){
  cart = cart.filter(i=>i.uid!==uidToRemove);
  renderBottomBars();
  renderCartSheet();
}

function cartTotals(){
  const subtotal = cart.reduce((a,i)=>a+i.unitPrice*i.qty,0);
  return {subtotal, total: subtotal};
}

function renderCartSheet(){
  const sheet = document.getElementById('sheetCart');

  if(checkoutStage==='cart'){
    const {subtotal,total} = cartTotals();
    sheet.innerHTML = `
      <button class="sheet-close" onclick="closeCart()">✕</button>
      <p class="sheet-title">Sacola</p>
      ${cart.length===0 ? `
        <div class="cart-empty"><span class="em"><img class="ui-icon" style="width:46px;height:46px;margin:auto" src="data:image/svg+xml;base64," alt=""></span>Sua sacola está vazia.<br>Adicione bebidas ou petiscos deliciosos!</div>
      ` : `
        <div class="cart-items">
          ${cart.map(item => `
            <div class="cart-item">
              ${item.photo ? `<img src="${item.photo}" onerror="this.outerHTML='<div class=&quot;ph&quot;>${item.icon}</div>'">` : `<div class="ph" style="width:56px;height:56px;background:#f3ead2;border-radius:12px;">${item.icon}</div>`}
              <div class="cart-item-info">
                <p class="cart-item-name">${item.name} ${item.qty>1? '× '+item.qty:''}</p>
                <div class="cart-item-tags">
                  <span>${SIZE_LABELS[item.size]}</span>
                  <span>${TEMP_LABELS[item.temp]}</span>
                </div>
                <div class="cart-item-bottom">
                  <span class="cart-item-price">${fmt(item.unitPrice*item.qty)}</span>
                  <button class="cart-item-remove" onclick="removeItem('${item.uid}')">remover</button>
                </div>
              </div>
            </div>
          `).join('')}
        </div>
        <div class="cart-summary">
          <div class="summary-row"><span>Subtotal</span><span>${fmt(subtotal)}</span></div>
          <div class="summary-row total"><span>Total</span><span>${fmt(total)}</span></div>
        </div>
      `}
      <div class="cart-actions">
        ${cart.length>0 ? `<button class="btn-continuar" onclick="goToPayment()">IR PARA PAGAMENTO</button>` : ''}
        <div class="row2">
          <button class="btn-outline" onclick="closeCart()">Continuar comprando</button>
          <button class="btn-outline" style="border-color:#c9846a;color:#c9846a;" onclick="cancelOrder()">Cancelar pedido</button>
        </div>
      </div>
    `;
  }

  if(checkoutStage==='payment'){
    sheet.innerHTML = `
      <button class="sheet-close" onclick="checkoutStage='cart'; renderCartSheet();">‹</button>
      <p class="sheet-title">Formas de pagamento</p>
      <button class="pay-option" onclick="choosePayment('dinheiro')">💵 DINHEIRO</button>
      <button class="pay-option" onclick="choosePayment('cartao')">💳 DÉBITO OU CRÉDITO</button>
      <button class="pay-option" onclick="choosePayment('pix')">🔳 PIX</button>
    `;
  }

  if(checkoutStage==='processing'){
    const isCard = selectedPayment==='cartao';
    sheet.innerHTML = `
      <p class="sheet-title">Formas de pagamento</p>
      <div class="confirm-wrap">
        <div class="loading-spinner" role="status" aria-label="Processando pagamento"></div>
        <p class="confirm-text">${isCard
          ? 'Siga as instruções da máquina de pagamento.'
          : 'Dirija-se ao caixa para pagamento e validação do pedido.'}</p>
        ${!isCard ? `<button class="btn-continuar" onclick="finishOrder()">CONCLUIR PEDIDO</button>` : ''}
      </div>
    `;
    if(isCard){
      setTimeout(()=>{ if(checkoutStage==='processing') finishOrder(); }, 2600);
    }
  }

  if(checkoutStage==='success'){
    sheet.innerHTML = `
      <div class="confirm-wrap">
        <span class="confirm-icon">✅</span>
        <p class="confirm-text">Pedido confirmado e validado!<br>Aguarde seu número ser chamado.</p>
        <div class="order-number">#${lastOrderNumber}</div>
        <button class="btn-continuar" onclick="backToHomeAfterOrder()">VOLTAR AO INÍCIO</button>
      </div>
    `;
  }
}

function goToPayment(){
  checkoutStage='payment';
  renderCartSheet();
}
function choosePayment(method){
  selectedPayment = method;
  checkoutStage='processing';
  renderCartSheet();
}
let lastOrderNumber = 0;
function finishOrder(){
  lastOrderNumber = Math.floor(100 + Math.random()*900);

  const pedido = montarPedidoParaPlanilha(lastOrderNumber);
  const enviado = enviarPedidoParaPlanilha(pedido);

  if(!enviado && GOOGLE_SCRIPT_URL.includes("COLE_AQUI")){
    console.warn("Pedido concluído localmente, mas a URL do Google Sheets ainda não foi configurada.");
  }

  checkoutStage='success';
  renderCartSheet();
}
function backToHomeAfterOrder(){
  cart = [];
  renderBottomBars();
  closeCart();
  checkoutStage='cart';
  showPage('home');
}


/* =========================================================
   INTEGRACAO COM GOOGLE SHEETS
========================================================= */
const GOOGLE_SCRIPT_URL = "COLE_/exec_AQUI";

function enviarPedidoParaPlanilha(pedido){
  if(
    !GOOGLE_SCRIPT_URL ||
    GOOGLE_SCRIPT_URL.includes("COLE_AQUI")
  ){
    console.warn("Google Sheets ainda não configurado.");
    return false;
  }

  if(!navigator.onLine){
    console.warn("O dispositivo está sem internet.");
    return false;
  }

  let iframe = document.getElementById("sheetsSubmitFrame");
  if(!iframe){
    iframe = document.createElement("iframe");
    iframe.id = "sheetsSubmitFrame";
    iframe.name = "sheetsSubmitFrame";
    iframe.style.display = "none";
    document.body.appendChild(iframe);
  }

  const form = document.createElement("form");
  form.method = "POST";
  form.action = GOOGLE_SCRIPT_URL;
  form.target = "sheetsSubmitFrame";
  form.style.display = "none";

  const field = document.createElement("input");
  field.type = "hidden";
  field.name = "pedido";
  field.value = JSON.stringify(pedido);

  form.appendChild(field);
  document.body.appendChild(form);
  form.submit();

  setTimeout(() => form.remove(), 1500);
  return true;
}

function montarPedidoParaPlanilha(numeroPedido){
  const {subtotal,total} = cartTotals();

  return {
    numero: numeroPedido,
    dataHora: new Date().toLocaleString("pt-BR"),
    pagamento: selectedPayment || "Não informado",
    subtotal: subtotal,
    total: total,
    status: "Novo",
    itens: cart.map(item => ({
      nome: item.name,
      quantidade: item.qty,
      tamanho: item.size || "",
      temperatura: item.temp || "",
      precoUnitario: item.unitPrice,
      totalItem: item.unitPrice * item.qty
    }))
  };
}


/* =========================================================
   INIT
========================================================= */
// Mascote da splash já está incorporado diretamente no HTML.
renderAllGrids();
renderBanner();
renderBottomBars();
